# -*- coding: utf-8 -*-
from pathlib import Path
import json,html
from sample_identity import sample_label
from service_icons import service_icon
P=Path(__file__).resolve().parent
D=P.parent.parent/'public/websample'
def write(name,s):(D/name).write_text(s,encoding='utf-8')
S=json.loads((P/'samples.json').read_text(encoding='utf-8'))
from expansion_data import expanded_samples, ROWS
base=S[0]
new_ids={row['id'] for row in ROWS}
S=[sample for sample in S if sample['id'] not in new_ids]+expanded_samples(base)
(P/'samples.json').write_text(json.dumps(S,ensure_ascii=False,indent=2))
write('assets/favicon.svg',(D.parent/'branding/stealth-favicon.svg').read_text())
