def card(s):
 if s.get('variant'):
  search=html.escape(' '.join(str(s[k]) for k in ['category','name','mood','label','sample_code','design_name'])+' '+s['sample_code'].replace('-','')+' '+s['design_name'].replace(' ',''),quote=True)
  return f'''<a class="sample-card" href="samples/{s['id']}.html" target="_blank" rel="noopener" data-category="{s['group']}" data-sector="{s['sector']}" data-search="{search}" data-sample-code="{s['sample_code']}" aria-label="{html.escape(sample_label(s))} 샘플 보기 (새 창)"><div class="card-art card-rendered-preview" style="background:{s['bg']}"><img src="assets/sample-previews/{s['id']}.webp" alt="" width="1200" height="700" loading="lazy"></div><div class="card-info"><div class="card-identity"><span class="sample-code">{s['sample_code']}</span><span class="sample-category">{s['category']}</span><span class="sample-new">NEW</span></div><div class="card-info-top"><h2>{s['design_name']}</h2></div><div class="card-bottom"><span class="view">샘플 보기</span></div></div></a>'''
 text=s.get('text',s['accent'])
 bg=s['bg']
 return f'''<a class="sample-card" href="samples/{s['id']}.html" target="_blank" rel="noopener" data-category="{s['group']}" data-sector="{s['sector']}" data-search="{html.escape(s['category']+' '+s['name']+' '+s['mood']+' '+s['label']+' '+s['sample_code']+' '+s['sample_code'].replace('-','')+' '+s['design_name']+' '+s['design_name'].replace(' ',''),quote=True)}" data-sample-code="{s['sample_code']}" aria-label="{html.escape(sample_label(s))} 샘플 보기 (새 창)"><div class="card-art art-{s['id']} layout-{s['layout']}" style="--card-bg:{bg};--sample-bg:{bg};--sample-text:{text};--sample-accent:{s['accent']};--button-ink:{s.get('buttonInk','#fff')}"><div class="card-browser" aria-hidden="true"><div class="window-bar"><i></i><i></i><i></i><span>{s['en'].lower().replace(' ','')}</span></div><div class="card-site-nav"><b>{s['name']}</b><span>ABOUT SERVICE CONTACT</span></div><div class="card-scene"><div class="card-scene-copy"><small>{s['en']}</small><strong>{s['short']}</strong><i>{s['cta']}</i></div><img src="assets/{s['image']}.webp" alt="" loading="lazy" width="600" height="400"></div></div></div><div class="card-info"><div class="card-identity"><span class="sample-code">{s['sample_code']}</span><span class="sample-category">{s['category']}</span></div><div class="card-info-top"><h2>{s['design_name']}</h2></div><div class="card-bottom"><span class="view">샘플 보기</span></div></div></a>'''
filters='<div class="filters" role="group" aria-label="샘플 카테고리"><button data-filter="all" aria-pressed="true">전체</button><button data-filter="company" aria-pressed="false">기업</button><button data-filter="factory" aria-pressed="false">제조·공장</button><button data-filter="local" aria-pressed="false">소상공인</button></div>'
search='<label class="catalogue-search"><span class="sr-only">업종·번호·디자인 이름으로 검색</span><input type="search" id="sample-search" placeholder="업종·번호·이름 검색" aria-controls="sample-cards"></label>'
index=head('홈페이지 디자인 샘플','기업·제조·공장·소상공인을 위한 홈페이지 디자인 샘플 30종. 번호와 이름으로 원하는 샘플을 확인하세요.')+'''<body class="catalogue-page"><a class="skip" href="#main">본문 바로가기</a><header class="catalogue-header"><div class="wrap"><h1>홈페이지 디자인 샘플</h1></div></header><main id="main"><section class="collection catalogue-collection" id="collection" aria-label="홈페이지 샘플 목록"><div class="wrap"><div class="catalogue-controls">'''+filters+search+f'<p class="catalogue-count" id="sample-count" role="status">전체 {len(S)}개 디자인</p>'+'''</div><div class="cards" id="sample-cards">'''+''.join(card(sample) for sample in sorted(S,key=lambda item:not bool(item.get('variant'))))+'''</div><div class="empty-search" id="empty-search" hidden><h2>검색 결과가 없습니다.</h2><p>다른 업종이나 샘플 번호로 찾아보세요.</p><button type="button" class="btn outline" id="reset-filters">전체 샘플 보기</button></div></div></section></main></body></html>'''
