# Static pages are hosted inside the existing Next.js application's subpath.
from urllib.parse import urlsplit,urlunsplit
import posixpath,re
for page in D.rglob('*.html'):
 directory=posixpath.dirname(page.relative_to(D).as_posix())
 def root_url(match):
  attr,url=match.groups();parsed=urlsplit(url)
  if parsed.scheme or parsed.netloc or not parsed.path or parsed.path.startswith('/'):return match.group(0)
  target=posixpath.normpath(posixpath.join(directory,parsed.path))
  if target.startswith('../'):raise ValueError(url)
  return f'{attr}="{urlunsplit(("","","/websample/"+target,parsed.query,parsed.fragment))}"'
 page.write_text(re.sub(r'\b(href|src)="([^\"]*)"',root_url,page.read_text()))

(P/'README.md').write_text('# Websample authoring\n\nRun `python3 tools/websample/build.py` from the repository root. The output is `public/websample`, already rooted at `/websample/`.\n\nOriginal concepts are recorded in samples.json. Twelve additional industry concepts and their copy are maintained in expansion_data.py; samples.json is refreshed on build. Shared footer compositions stay in footer_designs.py. Theme CSS and images live beside the static export. Service pictograms are mapped by sample and service in service_icons.py; the pinned Lucide SVG sources and ISC/MIT notices are bundled under public/websample/assets/icons/lucide.\n\nThe STEALTH logo is supplied artwork in public/branding. All browser titles and favicon links share that identity; fictional businesses retain their own in-page names.\n\nInquiry UI is maintained in inquiry.js and posts to /api/websample-inquiry. The Next.js route uses server-only SMTP_HOST, SMTP_PORT, SMTP_USER and SMTP_PASS. Its recipient is fixed to min@stealthinteractive.co.kr; missing SMTP configuration and delivery failures return errors. Run node --test tests/websample-inquiry.test.mjs after next build to test against an isolated local SMTP receiver without sending real mail.\n')
